export type ConsoleWork = "Run" | "Count" | "Transaction" | "Edit" | "Probe" | 
/**  An `All` export streams the result's source again. Cancellable like a run. */
"Export" | "Import";

export type CountError = { kind: "NotConnected" } | { kind: "Failed"; message: string };

/**  A user theme: one card in the picker, holding every variant it was created or imported with. */
export type CustomTheme = {
	id: string,
	name: string,
	variants: CustomThemeVariant[],
};

/**  `colors` maps the frontend's token names to CSS colours; the engine only stores it. */
export type CustomThemeVariant = {
	id: string,
	name: string,
	appearance: Appearance,
	colors: { [key in string]: string },
};

export type DatabaseKind = "Postgres" | "SqlServer";

/**
 *  One database on one saved connection. Postgres catalogs and OIDs are per database, so every
 *  catalog lookup, refresh, and count takes one of these. `database` is `pg_database.datname`.
 */
export type DatabaseRef = {
	connectionId: ConnectionId,
	database: string,
};

export type DatabaseState = {
	name: string,
	/**  `datistemplate OR NOT datallowconn`. `postgres` is an ordinary database. */
	system: boolean,
	access: DbAccess,
	/**
	 *  Whether the tree shows this database, resolved from the stored view. Never true without
	 *  `DbAccess::Ok`.
	 */
	shown: boolean,
	/**  The schema picker lists system schemas only while this is on. */
	showSystemSchemas: boolean,
	/**
	 *  The schemas the tree shows under this database, in name order. Empty until the catalog
	 *  serves a version.
	 */
	shownSchemas: string[],
	/**
	 *  Non-system schema count for the database picker: from the catalog when one is served,
	 *  else from `connection_probe_databases`.
	 */
	schemaCount: SchemaCount,
	catalog: CatalogStatus,
};

export type DbAccess = "Ok" | 
/**  `datallowconn` is false. */
"NoConnections" | 
/**  `has_database_privilege(datname, 'CONNECT')` is false. */
"NoPrivilege";

export type Decision = "Run" | "Deny";

export type DefaultValue = 
/**  `pg_get_expr` of the default, with the cast dropped from a lone literal: `'pending'`, `now()`. */
{ kind: "Expr"; sql: string } | 
/**  `GENERATED ALWAYS` (`always`) or `BY DEFAULT AS IDENTITY`. */
{ kind: "Identity"; always: boolean } | 
/**  `GENERATED ALWAYS AS (sql) STORED`, or `VIRTUAL` on PG 18. */
{ kind: "Generated"; sql: string };

export type Density = "Compact" | "Standard" | "Spacious";

export type DetailError = { kind: "Catalog"; error: CatalogError } | 
/**  The object was dropped after the catalog the caller holds was read. */
{ kind: "Gone" } | { kind: "Failed"; message: string };

export type DisconnectError = { kind: "OpenTransactions"; tabs: OpenTxn[] } | { kind: "Store"; message: string };

/**  UTF-16 code-unit offset into the editor document as sent in `RunRequest::Script.text`. */
export type DocOffset = number;

export type DocRange = {
	from: DocOffset,
	to: DocOffset,
};

export type DrillError = { kind: "Gone" } | { kind: "OutOfRange" } | 
/**  The result's SQL is not a `SELECT` with `FROM` and `GROUP BY`, so a point stands for no group of rows. */
{ kind: "Ungrouped" } | 
/**  The result's SQL cannot be rewritten to read exactly the rows behind a point. */
{ kind: "Unsupported"; reason: string };

/**  The chart point to open the rows behind. `Probe` asks only whether the result allows it. */
export type DrillPoint = { kind: "Probe" } | 
/**
 *  A stored row of the result, which is the chart's point at that index. `title` names the
 *  result's tab in the comment the SQL starts with.
 */
{ kind: "Row"; row: number; title: string };

/**
 *  The SQL behind a chart point, with the database and schema the result was read from. The new cell
 *  runs there, not wherever the chart's cell points now.
 */
export type DrillQuery = {
	/**  Empty for a probe. */
	sql: string,
	db: DatabaseRef,
	schema: string | null,
};

/**  An effort level as its provider names it (`high`). Valid only for a model that lists it. */
export type EffortId = string;

export type EffortOption = {
	id: EffortId,
	label: string,
};

/**  Stored verbatim in `chat_entries.json`. A stored row this build cannot parse loads as `Unreadable`. */
export type Entry = { kind: "User"; atMs: number; text: string; context: SentContext | null; attachment: Attachment | null } | { kind: "Text"; blocks: ReplyBlock[]; done: boolean } | { kind: "Tool"; call: ToolCallId; tool: ToolUse; status: ToolStatus } | 
/**  Shown when the engine had to change course, such as a lost provider session. */
{ kind: "Notice"; text: string } | 
/**  Closes every turn. */
{ kind: "End"; atMs: number; outcome: TurnOutcome; suggestions: string[] } | { kind: "Unreadable" };

export type EntrySnapshot = {
	chatId: ChatId,
	seq: number,
	rev: number,
	/**  The seq of the user entry that opened this entry's turn. A user entry names itself. */
	turn: number,
	entry: Entry,
};

/**  What the user says the connection points at. The UI marks `Production`, and the engine asks before a write runs on it. */
export type Environment = "Local" | "Staging" | "Production";

export type ExecutionUnitKind = "Statement" | "Batch";

export type Expect = 
/**  Only `keywords`, which may be empty, as after a relation's alias. */
{ kind: "Keyword" } | 
/**  Right after a relation, where the word typed is most likely its alias, so `keywords` show only on request. */
{ kind: "Alias" } | 
/**  A table, view, or CTE: after `FROM`, `JOIN`, `INTO`, or `UPDATE`. */
{ kind: "Relation" } | 
/**  Columns and functions: a select list, `WHERE`, `ON` once a condition has begun, `SET`. */
{ kind: "Expression" } | 
/**  Right after the `ON` of the join to `relations[target]`. */
{ kind: "JoinCondition"; target: number };

/**  Every variant leaves the file at the chosen path as it was. */
export type ExportError = 
/**  A newer run replaced the result, or its tab closed. */
{ kind: "Gone" } | 
/**  The file could not be created, written, synced, or moved into place. */
{ kind: "Io"; message: string } | 
/**  `All` for a result whose `allRows` is `Refused`. */
{ kind: "NotRerunnable" } | 
/**  The tab's session is held by a run, a count, a transaction command, an edit, or another export. */
{ kind: "Busy" } | 
/**  The tab now targets another connection or database than the one the rows came from. */
{ kind: "TargetChanged" } | 
/**  The tab's transaction failed; only a rollback runs until it ends. */
{ kind: "TransactionAborted" } | { kind: "Connect"; error: ConnectError } | 
/**  The source failed on the server when it ran again. */
{ kind: "Query"; error: QueryError } | 
/**  The source returned other columns, or fewer result sets, than when it first ran. */
{ kind: "ShapeChanged" } | 
/**  Esc stopped the export before the file was in place. */
{ kind: "Cancelled" };

export type ExportFormat = 
/**  RFC 4180 with CRLF and a header row, NULL as an empty field, as `COPY … CSV` writes it. */
"Csv" | 
/**  An array of objects keyed by column name, one per line. Values are typed by `TypeCategory`. */
"Json" | 
/**  A GitHub table. */
"Markdown" | 
/**  One `INSERT` per row, quoted for the result's dialect. */
"SqlInsert";

export type ExportProgress = {
	result: ResultRef,
	format: ExportFormat,
	/**  Rows encoded so far. */
	rows: number,
	/**  Bytes handed to the file so far. */
	bytes: number,
	/**
	 *  Writing failed while SQL Server is still sending. The export reads to the end so the session and
	 *  its transaction survive; the file is not written. Esc stops it at once and resets the session.
	 */
	writeError: string | null,
};

export type ExportScope = 
/**  The rows the engine holds for the result, capped by the row and size limits. */
"Loaded" | 
/**  Every row: the result's source runs again on its tab's session and streams to the file. */
"All";

export type ExportSummary = {
	rows: number,
	bytes: number,
	/**  The loaded rows stopped at the row or size limit. Always false for `All`. */
	truncated: boolean,
};

export type ExtensionInfo = {
	oid: number,
	name: string,
	quoted: string,
	version: string,
};

/**  Made only by the engine (`notebook_open`, `notebook_save`); the frontend stores it whole and hands it back whole. */
export type FileBinding = {
	/**  The canonical folder joined with the file's own name: `..` and folder symlinks collapse, a symlink keeps its name. */
	path: string,
	stamp: FileStamp,
	format: FileFormat,
};

/**
 *  How the file's bytes differ from the LF, BOM-less text the editor holds. A save writes them back, with every
 *  line break as CRLF when the file's first break was.
 */
export type FileFormat = {
	bom: boolean,
	crlf: boolean,
};

export type FileReadError = { kind: "NotFound" } | { kind: "NotAFile" } | { kind: "PermissionDenied" } | 
/**  `offset` counts from the start of the file, BOM included. */
{ kind: "NotUtf8"; offset: number } | { kind: "TooLarge"; bytes: number; limit: number } | { kind: "Io"; message: string };

export type FileSnapshot = {
	binding: FileBinding,
	/**  The tab's `text` differed from the file when this snapshot was taken. */
	dirty: boolean,
};

/**
 *  Opaque outside `files.rs`, which makes it from the file's bytes; everything else only compares two for
 *  equality. A stamp this build does not make never equals a fresh one, so the file reads as changed.
 */
export type FileStamp = string;

export type FileWriteError = 
/**  The file changed on disk; nothing was written. `disk` is the stamp of what is there now. */
{ kind: "Changed"; disk: FileStamp } | 
/**  The folder the file goes in does not exist. */
{ kind: "NotFound" } | { kind: "NotAFile" } | { kind: "PermissionDenied" } | 
/**  `path` is the other notebook's, which may name the file differently: a symlink, a hard link, another case. */
{ kind: "OpenInAnotherNotebook"; path: string } | { kind: "Io"; message: string };

export type FilterOp = "Eq" | "Ne" | "Lt" | "Le" | "Gt" | "Ge" | "Contains" | "StartsWith" | "IsNull" | "NotNull";

export type FkAction = "NoAction" | "Restrict" | "Cascade" | "SetNull" | "SetDefault";

export type FnKind = "Function" | "Procedure" | "Aggregate" | "Window";

/**  `family` is a name the frontend's font registry resolves to a CSS stack; unknown names pass through. */
export type FontSetting = {
	family: string,
	size: number,
};

/**  Replace `from..to` with `insert`: the formatted statements and the original text between them. */
export type FormatEdit = {
	from: DocOffset,
	to: DocOffset,
	insert: string,
};

export type FormatError = { kind: "Unsupported" } | 
/**  No statement at the cursor or in the selection. */
{ kind: "NothingToFormat" } | 
/**  The laid-out text would lex differently from the original, so the engine refused it. */
{ kind: "Unsafe" };

export type FunctionInfo = {
	oid: number,
	name: string,
	/**  `name` as a call writes it, quoted only when it must be. */
	quoted: string,
	args: string,
	returns: string,
	kind: FnKind,
	insertText: string,
};

/**  Values from `lo` up to `hi`. The last bin also holds `hi`. */
export type HistogramBin = {
	lo: number | null,
	hi: number | null,
	count: number,
};

export type HistoryBrowsePage = {
	groups: HistoryGroupSummary[],
	counts: HistoryCounts,
	hasMore: boolean,
	revision: number,
};

export type HistoryBrowseQuery = {
	text: string | null,
	filter: HistoryFilter,
	beforeId: number | null,
	limit: number,
	revision: number | null,
};

export type HistoryCounts = {
	all: number,
	failed: number,
	writes: number,
};

export type HistoryEntry = {
	databaseKind: DatabaseKind,
	id: number,
	atMs: number,
	connectionId: ConnectionId,
	connectionName: string,
	database: string,
	sql: string,
	elapsedMs: number,
	outcome: HistoryOutcome,
};

export type HistoryError = { kind: "Stale" } | { kind: "Unavailable"; message: string };

export type HistoryFilter = "All" | "Failed" | "Writes";

export type HistoryGroupPage = {
	databaseKind: DatabaseKind,
	sql: string,
	runs: HistoryRun[],
	hasMore: boolean,
	maxElapsedMs: number,
	revision: number,
};

export type HistoryGroupQuery = {
	id: number,
	beforeId: number | null,
	limit: number,
	revision: number,
};

export type HistoryGroupSummary = {
	databaseKind: DatabaseKind,
	id: number,
	latestId: number,
	latestAtMs: number,
	connectionId: ConnectionId,
	database: string,
	title: string,
	excerpt: string,
	runCount: number,
	failedCount: number,
	isWrite: boolean,
	representative: HistoryRun,
};

export type HistoryOutcome = { kind: "Rows"; rows: number } | { kind: "Command"; tag: string } | { kind: "Error"; message: string } | { kind: "Cancelled" };

export type HistoryPage = {
	entries: HistoryEntry[],
	hasMore: boolean,
};

export type HistoryQuery = {
	text: string | null,
	connectionId: ConnectionId | null,
	beforeId: number | null,
	limit: number,
};

export type HistoryRun = {
	id: number,
	atMs: number,
	connectionName: string,
	elapsedMs: number,
	outcome: HistoryOutcome,
};

/**  Engine-wide monotonic. Names one host key the engine observed and is holding for a trust decision. */
export type HostKeyId = number;

export type ImportError = { kind: "NotConfigured" } | { kind: "Unsupported" } | { kind: "Busy" } | { kind: "Gone" } | { kind: "TargetChanged" } | { kind: "TransactionAborted" } | { kind: "Cancelled" } | { kind: "Io"; message: string } | { kind: "Csv"; line: number; record: number; message: string } | { kind: "Mapping"; message: string } | { kind: "Connect"; error: ConnectError } | { kind: "Query"; error: QueryError } | { kind: "OutcomeUnknown"; error: QueryError } | { kind: "ConfirmWrites"; confirmation: WriteConfirmation };

export type ImportPreview = {
	source: ImportSourceId,
	target: ImportTarget,
	bytes: number,
	rows: number,
	fields: string[],
	columns: ColumnInfo[],
	mapping: (string | null)[],
	sample: ((string | null)[])[],
	truncated: boolean,
};

export type ImportProgress = {
	source: ImportSourceId,
	target: ImportTarget,
	bytes: number,
	totalBytes: number,
	rows: number,
	totalRows: number,
	finishing: boolean,
};

export type ImportRequest = {
	source: ImportSourceId,
	header: boolean,
	mapping: (string | null)[],
};

export type ImportSourceId = string;

export type ImportSummary = {
	backendPid: number,
	rows: number,
	committed: boolean,
};

export type ImportTarget = {
	db: DatabaseRef,
	schema: string,
	table: string,
	oid: number,
};

export type IndexInfo = {
	name: string,
	/**  `pg_am.amname`: btree, hash, gin, gist, brin. */
	method: string,
	unique: boolean,
	primary: boolean,
	/**  False while `CREATE INDEX CONCURRENTLY` builds it or after that failed. */
	valid: boolean,
	/**  The key list cut from `pg_get_indexdef`: `(created_at DESC)`, `(a) INCLUDE (b)`. */
	keys: string,
	/**  The predicate of a partial index, without redundant parentheses: `status <> 'paid'::text`. */
	predicate: string | null,
};

export type InstallReply = 
/**  Nothing was installed. Show `impact`, then call again with it as the acceptance. */
{ kind: "Confirm"; impact: RestartImpact } | { kind: "Restarting" };

/**
 *  Every database of the instance, with the state of its catalog. The connection snapshot is the
 *  single source of catalog versions.
 */
export type InstanceState = {
	configuredDatabase: string,
	/**  `ConnectionConfig.database` as the server spells it. */
	home: string,
	/**  The database picker lists system databases only while this is on. */
	showSystemDatabases: boolean,
	/**  Every row of `pg_database`, sorted by name. */
	databases: DatabaseState[],
};

export type KeyInfo = {
	name: string,
	/**  In key order. */
	columns: string[],
	kind: KeyKind,
};

export type KeyKind = { kind: "Primary" } | { kind: "Unique" } | { kind: "Foreign"; refSchema: string; refTable: string; refColumns: string[]; onDelete: FkAction; onUpdate: FkAction } | 
/**  `definition` is `pg_get_constraintdef`: `CHECK ((qty > 0))`. */
{ kind: "Check"; definition: string };

export type Layout = {
	sidebar: boolean,
	results: boolean,
	rightPanel: RightPanel | null,
	resultsHeight: number,
	sidebarWidth: number,
	rightPanelWidth: number,
	assistantChat: ChatId | null,
};

export type LimitLevel = "Normal" | "Low" | "Exhausted";

export type LimitWindow = {
	/**  Stable within a source: "session", "weekly_all", "weekly_scoped:Opus". */
	id: string,
	/**  "Session", "Weekly", "Weekly · Opus". */
	label: string,
	/**  Remaining, 0..=100. */
	leftPercent: number,
	resetsAtMs: number | null,
	level: LimitLevel,
};

export type LimitsOutcome = 
/**  `plan` is the short tier the header shows after the name: "Max". */
{ kind: "Ready"; plan: string | null; windows: LimitWindow[] } | 
/**  Signed in with no subscription limits: an API key, Bedrock, Vertex. */
{ kind: "NoLimits"; plan: string | null } | { kind: "SignedOut"; signInCommand: string } | { kind: "NotFound"; binary: string } | 
/**  The CLI started but the exchange failed, timed out, or returned a shape we cannot read. */
{ kind: "Failed"; message: string };

export type LimitsReport = {
	/**  When the last read finished. */
	checkedAtMs: number,
	/**  One per `ProviderKind::ALL`, in that order. */
	sources: SourceLimits[],
};

export type MapColumnPair = {
	source: string,
	target: string,
};

export type MapCursor = {
	db: DatabaseRef,
	root: number,
	catalogVersion: number,
	lastConstraint: number,
};

export type MapError = { kind: "Catalog"; error: CatalogError } | { kind: "Gone" } | { kind: "Stale" } | { kind: "Failed"; message: string };

export type MapForeignKey = {
	id: number,
	name: string,
	source: number,
	target: number,
	columns: MapColumnPair[],
	enabled: boolean,
	validated: boolean,
};

export type MapNeighborhood = {
	db: DatabaseRef,
	catalogVersion: number,
	root: MapRelation,
	relations: MapRelation[],
	foreignKeys: MapForeignKey[],
	after: MapCursor | null,
};

export type MapOccurrence = {
	id: number,
	name: string,
	alias: string | null,
	range: DocRange,
	resolution: MapResolution,
};

export type MapQuery = {
	db: DatabaseRef,
	catalogVersion: number,
	statement: DocRange | null,
	occurrences: MapOccurrence[],
	joins: MapQueryJoin[],
	incomplete: boolean,
};

export type MapQueryJoin = {
	source: number,
	target: number,
	columns: MapColumnPair,
	range: DocRange,
};

export type MapRelation = {
	oid: number,
	schema: string,
	name: string,
	columns: string[],
};

export type MapResolution = { kind: "CatalogMatch"; oid: number } | { kind: "Tentative"; oid: number } | { kind: "Unresolved"; reason: string };

export type MetaPair = {
	key: string,
	value: string,
};

/**  A model as its provider names it on its command line (`opus`). Valid only against the last probe. */
export type ModelId = string;

export type ModelOption = {
	id: ModelId,
	label: string,
	description: string,
	/**  Empty when the model takes no effort setting. */
	efforts: EffortOption[],
	/**  New chats start on it. */
	recommended: boolean,
};

export type NotebookCell = {
	text: string,
	meta: CellMeta,
};

export type NotebookFileSnapshot = {
	binding: FileBinding,
	/**  The cells differed from the file when this snapshot was taken. */
	dirty: boolean,
	/**  The file holds plain SQL, with no header and no cell marker. */
	plain: boolean,
	unknown: UnknownKeys,
};

/**  Names the database the notebook was on. A file never holds a host, a user, a password, or a connection id. */
export type NotebookHeader = {
	/**  The connection's display name. */
	connection: string | null,
	kind: DatabaseKind | null,
	database: string | null,
	/**  Keys this build does not read, written back as they were. */
	unknown: MetaPair[],
};

/**  Minted by the frontend (`crypto.randomUUID()`). */
export type NotebookId = string;

export type NotebookOpened = {
	binding: FileBinding,
	/**  The file's name. */
	name: string,
	notebook: NotebookText,
};

export type NotebookSaved = {
	binding: FileBinding,
	name: string,
	/**  The file holds plain SQL, with no header and no cell marker. */
	plain: boolean,
};

/**  One of a database's notebooks. Every cell in it is on `db`. */
export type NotebookSnapshot = {
	id: NotebookId,
	title: string,
	/**  `None` holds the cells that have no connection. */
	db: DatabaseRef | null,
	/**  The notebook's cells in order. Each id is a `TabSnapshot` in `Workspace.tabs`. */
	cells: TabId[],
	active: TabId | null,
	/**  When the notebook was last shown, in Unix milliseconds. Choosing a database shows its most recent notebook. */
	shownAtMs: number,
	/**  `None` for a notebook not saved to a file. */
	file: NotebookFileSnapshot | null,
};

/**  A notebook as its file holds it. Only `notebook_file` reads or writes the file's text. */
export type NotebookText = {
	/**
	 *  Read: the file has no header and no cell marker, so it is one cell holding the whole file. Save: print the
	 *  notebook that way while it still reads back the same, as one cell with nothing else to record.
	 */
	plain: boolean,
	header: NotebookHeader,
	/**  At least one when read. */
	cells: NotebookCell[],
};

/**  The DDL that creates one object. */
export type ObjectScript = {
	/**  The tab title: the object's name and `.sql`. */
	title: string,
	/**  Starts with one `-- L1 Data could not script: ...` line per warning. */
	text: string,
	/**  The properties of the object that `text` does not recreate. */
	warnings: string[],
};

/**  A console whose transaction would be lost by a disconnect, a close, or a restart. */
export type OpenTxn = {
	tabId: TabId,
	hasWrites: boolean,
};

export type OutputBody = 
/**  Logged when the statement starts, before its notices and its result line. */
{ kind: "Statement"; statement: number; text: string } | { kind: "Rows"; statement: number; rows: number; elapsedMs: number; truncated: boolean } | { kind: "Command"; statement: number; tag: string; elapsedMs: number } | { kind: "Notice"; severity: string; message: string; detail: string | null } | 
/**  `statement` is `None` for a failure no statement owns, such as `SET search_path`. */
{ kind: "Error"; statement: number | null; error: QueryError } | { kind: "Info"; message: string };

/**
 *  One line of a tab's output log: timestamped history of what the session ran and what the
 *  server said. Statement outcomes also live in `ConsoleState.run`; that snapshot is the current
 *  status, this log is the history. `run_id` is the run, commit, rollback, or apply that held the
 *  session; run ids share one counter, so a later entry never carries a lower id.
 */
export type OutputEntry = {
	atMs: number,
	runId: RunId,
	body: OutputBody,
};

export type Param = {
	name: string,
};

export type ParamValue = {
	name: string,
	value: string | null,
};

export type PasswordInput = "Keep" | { Set: string } | "Clear";

export type Permission = 
/**  Every `run_query` waits for Run or Deny. */
"AskFirst" | 
/**
 *  A read that calls only vetted built-in functions runs without asking. Anything else asks,
 *  with `ApprovalReason::Unvetted` naming what.
 */
"Auto";

export type Plan = {
	statements: StatementPlan[],
};

export type PlanBuffers = {
	sharedHit: number,
	sharedRead: number,
	sharedDirtied: number,
	sharedWritten: number,
	localHit: number,
	localRead: number,
	localDirtied: number,
	localWritten: number,
	tempRead: number,
	tempWritten: number,
};

export type PlanFormat = "Json" | "Xml";

export type PlanNode = {
	operation: string,
	detail: string,
	startupCost: number | null,
	totalCost: number | null,
	planRows: number | null,
	actualRows: number | null,
	loops: number | null,
	totalTimeMs: number | null,
	selfTimeMs: number | null,
	diverges: boolean,
	buffers: PlanBuffers | null,
	properties: PlanProperty[],
	children: PlanNode[],
};

export type PlanProperty = {
	name: string,
	value: string,
};

/**  The quick actions of a picker. `None` is an explicit empty selection. */
export type Preset = "All" | "DefaultOnly" | "None";

export type ProbeOutcome = { kind: "Ready"; version: string; plan: string | null; models: ModelOption[] } | { kind: "SignedOut"; version: string } | { kind: "NotFound"; binary: string } | 
/**  Found, but the version check, the sign-in check, or the handshake failed or timed out. */
{ kind: "Broken"; version: string | null; message: string };

export type ProfileSummary = 
/**
 *  An integer or numeric column, not `money` or `smallmoney`, whose every non-null text parses.
 *  `min`, `mean`, and `max` are exact decimal text, as the selection totals print them.
 *  The histogram spans the finite values only, and is empty when there are none.
 */
{ kind: "Numeric"; min: string; mean: string; max: string; histogram: HistogramBin[] } | 
/**  Every other column: at most five of the most frequent non-null values, cut like a page cell. */
{ kind: "Values"; top: ValueCount[] };

export type ProviderConfig = {
	provider: ProviderKind,
	enabled: boolean,
	displayName: string,
	/**  Empty means the provider's binary name, looked up on the login shell's PATH. `~` expands. */
	binaryPath: string,
	/**  Empty means the inherited environment variable, else the provider's default directory. */
	configDir: string,
	/**  Extra arguments as typed. The provider drops the flags the engine owns. */
	launchArgs: string,
};

/**  What never changes for a kind. */
export type ProviderInfo = {
	defaultName: string,
	defaultBinary: string,
	/**  The environment variable that names the config directory: `CLAUDE_CONFIG_DIR`. */
	configEnv: string,
	configDirDefault: string,
	signInCommand: string,
	/**  Launch-argument flags the engine ignores, listed under the field. */
	ownedFlags: string[],
};

export type ProviderKind = "Claude";

export type ProviderState = {
	/**  Not `kind`: `AppEvent` is tagged on `kind`. */
	provider: ProviderKind,
	rev: number,
	info: ProviderInfo,
	/**  The engine-owned flags in the saved launch arguments, as typed, which it drops. */
	ignoredFlags: string[],
	/**  A probe runs. `outcome` stays on screen meanwhile. */
	checking: boolean,
	checkedAtMs: number | null,
	/**  `None` until the first probe finishes. */
	outcome: ProbeOutcome | null,
};

export type Qualifier = 
/**  The alias or name of `relations[index]`. */
{ kind: "Relation"; index: number } | 
/**  Names that match no relation in scope, such as a schema. Unquoted PostgreSQL names are folded to lower case. */
{ kind: "Name"; parts: string[] };

export type QueryError = {
	severity: string,
	sqlstate: string | null,
	message: string,
	detail: string | null,
	hint: string | null,
	context: string | null,
	position: DocOffset | null,
};

/**  `System` follows the operating system's reduce-motion accessibility setting. */
export type ReduceMotion = "System" | "On" | "Off";

export type RelKind = "Table" | "PartitionedTable" | "View" | "MaterializedView" | "ForeignTable";

export type Relation = {
	qualifiedName: string,
	oid: number,
	name: string,
	/**  `name` as SQL writes it, quoted only when it must be. */
	quoted: string,
	kind: RelKind,
	/**  `None` when `reltuples = -1` (never analyzed). */
	rowEstimate: number | null,
	/**  In `attnum` order. */
	columns: ColumnInfo[],
};

/**
 *  What a table row shows past its columns, read by `relation_detail` when the row first opens.
 *  It is not in `Catalog`, so a DDL refresh never scans constraints, indexes, and triggers.
 */
export type RelationDetail = {
	db: DatabaseRef,
	oid: number,
	/**  The catalog version the detail is at least as new as. */
	catalogVersion: number,
	/**  In `attnum` order. */
	defaults: ColumnDefault[],
	/**  Primary, then foreign, unique, and check, each by name. */
	keys: KeyInfo[],
	/**  Primary, then unique, then the rest, each by name. */
	indexes: IndexInfo[],
	/**  By name. */
	triggers: TriggerInfo[],
};

export type RelationSource = 
/**  A catalog table or view. Unquoted PostgreSQL names are folded to lower case. */
{ kind: "Table"; schema: string | null; name: string } | 
/**
 *  A CTE, a subquery, or a table function: the columns its select list names, as SQL writes them, plus every
 *  column of each `star` table.
 */
{ kind: "Derived"; columns: string[]; star: TableName[] };

/**  What one release changed, as the feed lists it. Display only. */
export type ReleaseChanges = {
	version: string,
	items: ChangeItem[],
};

export type ReplyBlock = { kind: "Markdown"; text: string } | 
/**  A fenced SQL block. `relations` and `vetted` are filled when the fence closes. */
{ kind: "Sql"; sql: string; relations: string[]; vetted: boolean; complete: boolean };

/**
 *  Everything a restart would end, as of the call. The frontend sends it back as what the user
 *  accepted, and the engine installs only if that still covers what a restart would end.
 */
export type RestartImpact = {
	/**  Tabs with a run, count, commit, rollback, or staged-edit apply in flight. */
	running: TabId[],
	transactions: OpenTxn[],
	/**  Chats with a running assistant turn. */
	chats: ChatId[],
};

export type ResultCell = {
	row: number,
	col: number,
};

export type ResultError = { kind: "Gone" } | { kind: "OutOfRange" } | { kind: "NotAPlan"; what: string };

export type ResultFind = {
	count: number,
	target: ResultFindTarget | null,
	rowCount: number,
};

export type ResultFindDirection = { kind: "First" } | { kind: "Next"; anchor: ResultCell } | { kind: "Previous"; anchor: ResultCell };

export type ResultFindTarget = {
	cell: ResultCell,
	ordinal: number,
};

export type ResultMeta = {
	databaseKind: DatabaseKind,
	ref: ResultRef,
	/**
	 *  The database the rows came from. Column sources are its OIDs, so PK lookups key on this,
	 *  not on the tab's current target, which a retarget can change under an old result.
	 */
	db: DatabaseRef,
	columns: ColumnMeta[],
	/**  Rows stored and pageable. */
	rowCount: number,
	/**  Rows the server sent; greater than `row_count` when truncated. */
	rowsSeen: number,
	truncated: TruncateReason | null,
	elapsedMs: number,
	/**  What `ExportScope::All` would run for this result. Decided once, when the result was created. */
	allRows: AllRows,
};

export type ResultRef = {
	tabId: TabId,
	runId: RunId,
	index: number,
};

export type RightPanel = "Assistant";

export type RowPage = {
	start: number,
	rows: ((string | null)[])[],
	cut: ([number, number])[],
};

/**  Inclusive indexes into the stored rows. */
export type RowSpan = {
	start: number,
	end: number,
};

export type RowUpdate = {
	key: CellWrite[],
	set: CellWrite[],
};

export type RowsState = "Streaming" | "Complete" | "Failed" | "Cancelled";

export type RunAccepted = {
	runId: RunId,
	statements: DocRange[],
	/**  Each cell the run inlined for a reference, directly or through another cell, once, with the text it used. */
	sources: CellSource[],
};

export type RunError = { kind: "Busy" } | { kind: "NoStatement" } | { kind: "NotConfigured" } | 
/**  `what` names the construct, e.g. `"COPY FROM STDIN"`. */
{ kind: "Unsupported"; what: string } | { kind: "Connect"; error: ConnectError } | 
/**  WHERE or ORDER BY isn't a single expression, e.g. it smuggles in a second statement. */
{ kind: "BadFilter" } | { kind: "ConfirmWrites"; confirmation: WriteConfirmation } | 
/**  A `{{name}}` cannot expand. `message` is one sentence that names the cell. */
{ kind: "Reference"; message: string };

/**  Engine-wide monotonic. */
export type RunId = number;

export type RunMode = "Run" | "Explain" | "ExplainAnalyze";

export type RunOutcome = "Ok" | "Failed" | "Cancelled";

export type RunOutput = { kind: "Rows"; result: ResultMeta; state: RowsState } | { kind: "Command"; tag: string; affectedRows: number | null; elapsedMs: number } | { kind: "Plan"; result: ResultMeta; format: PlanFormat };

export type RunRequest = { kind: "script"; text: string; target: RunTarget; mode: RunMode; params: ParamValue[]; 
/**  Every cell of the running cell's notebook, which `{{title}}` references resolve against. */
cells?: CellSource[] } | { kind: "tablePage"; schema: string; table: string; page: number; query?: TableQuery };

export type RunState = { kind: "Idle" } | { kind: "Running"; runId: RunId; startedAtMs: number; statements: StatementRun[] } | { kind: "Finished"; runId: RunId; elapsedMs: number; statements: StatementRun[]; outcome: RunOutcome };

export type RunTarget = { kind: "cursor"; offset: DocOffset } | { kind: "selection"; from: DocOffset; to: DocOffset } | { kind: "all" };

export type SaveError = { kind: "Invalid"; message: string } | { kind: "Keychain"; message: string } | { kind: "Store"; message: string };

export type SaveQueryReply = {
	id: SavedQueryId,
	/**
	 *  The same text in the same dialect was already saved. `id` is that entry, and nothing was
	 *  written.
	 */
	alreadySaved: boolean,
	queries: SavedQueries,
};

export type SaveTarget = 
/**
 *  Refused with `Changed` when the file's bytes no longer match `binding.stamp`, unless they match
 *  `overwrite`, the `disk` stamp of the `Changed` the user agreed to overwrite.
 */
{ kind: "Bound"; binding: FileBinding; overwrite: FileStamp | null } | 
/**
 *  A path from the save dialog, which already asked before replacing a file. No stamp check. Refused with
 *  `OpenInAnotherNotebook` when it is the same file as one of `taken`, the paths the other notebooks are bound to.
 */
{ kind: "New"; path: string; format: FileFormat | null; taken: string[] };

/**
 *  Every readable saved query, most recently used first. `rev` rises with every write that
 *  changes a row.
 */
export type SavedQueries = {
	rev: number,
	items: SavedQuery[],
};

export type SavedQuery = {
	id: SavedQueryId,
	name: string,
	sql: string,
	databaseKind: DatabaseKind,
	/**  Derived on read, never stored: the SQL after its leading comments, cut to 180 characters. */
	excerpt: string,
	createdAtMs: number,
	/**
	 *  Set at creation and by `saved_query_used`. An edit leaves it alone, so an edit never
	 *  reorders the list.
	 */
	usedAtMs: number,
};

export type SavedQueryEdit = {
	/**  Blank means "name it from the SQL", the default a new query gets. */
	name: string,
	sql: string,
};

export type SavedQueryError = 
/**  The cursor is on no statement, or the selection or the edited SQL is blank. */
{ kind: "NothingToSave" } | { kind: "TooLong"; limitBytes: number } | 
/**  An edit of an id that no longer exists. Delete and use never return it. */
{ kind: "NotFound" } | { kind: "Store"; message: string };

/**
 *  Rowid of `saved_queries`. AUTOINCREMENT, so a deleted id is never reissued and a late click on
 *  a deleted entry cannot act on a newer one.
 */
export type SavedQueryId = number;

export type SchemaCount = { kind: "Unknown" } | { kind: "Probing" } | { kind: "Known"; count: number } | 
/**  The probe session failed; `message` is the server's or the transport's text. */
{ kind: "Unavailable"; message: string };

export type SchemaInfo = {
	name: string,
	/**  `name` as SQL writes it, quoted only when it must be. */
	quoted: string,
	/**  `information_schema` or a `pg_` prefix, which Postgres reserves for its own schemas. */
	system: boolean,
	/**
	 *  Tables, partitioned tables, and foreign tables, which the tree lists as tables. Counted by
	 *  the schema query itself, so it is right for a system schema whose `relations` are not loaded.
	 */
	tableCount: number,
	relations: Relation[],
	functions: FunctionInfo[],
	/**  User schemas only, by name. Includes identity and serial sequences. */
	sequences: SequenceInfo[],
	/**
	 *  Enums, domains, composites, and ranges in every loaded schema.
	 *  Base and pseudo types too, when this schema's relations loaded.
	 */
	types: TypeInfo[],
	/**  SQL Server only, by name. Empty on PostgreSQL, and no query runs there. */
	synonyms: SynonymInfo[],
};

export type ScopeRelation = {
	/**  How the statement refers to it, as written: its alias, else its name. `None` for a subquery without an alias. */
	reference: string | null,
	source: RelationSource,
	/**  The names a column alias list gives the first columns, as in `orders o(a, b)`, as SQL writes them. */
	columnAliases: string[],
};

/**  The statements of a script and the one a run at the cursor would pick. */
export type ScriptOutline = {
	unitKind: ExecutionUnitKind,
	statements: DocRange[],
	atCursor: number | null,
};

/**
 *  An object the tree can script. `oid` is the catalog id of a relation, routine, sequence, type,
 *  synonym, or extension. An index or trigger is named within its relation, as `RelationDetail` lists it.
 */
export type ScriptTarget = { kind: "Relation"; oid: number } | { kind: "Routine"; oid: number } | { kind: "Index"; relationOid: number; name: string } | { kind: "Trigger"; relationOid: number; name: string } | { kind: "Sequence"; oid: number } | { kind: "Type"; oid: number } | { kind: "Synonym"; oid: number } | { kind: "Extension"; oid: number };

export type SendError = { kind: "Busy" } | { kind: "EmptyMessage" } | { kind: "ProviderOff"; provider: ProviderKind } | 
/**  The chat's model left the provider's list since it was picked. */
{ kind: "UnknownModel"; model: ModelId } | 
/**  A newer run replaced the attached result. */
{ kind: "AttachmentGone" } | { kind: "Store"; message: string };

export type SendRequest = {
	text: string,
	tab: TabContext | null,
};

export type SentContext = {
	databaseKind: DatabaseKind | null,
	db: DatabaseRef | null,
	/**  As named at send, so the chip reads right after a rename or a delete. */
	connectionName: string | null,
	tabTitle: string,
};

export type SequenceInfo = {
	oid: number,
	name: string,
	quoted: string,
	typeName: string,
};

export type ServerInfo = {
	/**  `"16.4"` */
	version: string,
	versionNum: number,
	encoding: string,
};

export type SessionState = { kind: "None" } | { kind: "Open"; backendPid: number } | { kind: "Lost"; reason: string; transaction: TransactionLoss };

export type Settings = {
	assistantAccess: AssistantAccess,
	maxRows: number,
	maxResultBytes: number,
	tablePageSize: number,
	stopOnError: boolean,
	colorScheme: ColorScheme,
	/**  Theme id painted while the scheme resolves to light. */
	lightTheme: string,
	/**  Theme id painted while the scheme resolves to dark. */
	darkTheme: string,
	customThemes: CustomTheme[],
	interfaceFont: FontSetting,
	/**  Used by the SQL editor and the result grid. */
	codeFont: FontSetting,
	density: Density,
	/**  0 turns panel animation off. */
	panelMotionMs: number,
	/**  Reduced motion snaps panels open and closed and turns menu and dialog movement into a fade. */
	reduceMotion: ReduceMotion,
	/**  Shade each colored connection in the sidebar tree instead of drawing its dot. */
	tintConnections: boolean,
	/**  One per `ProviderKind::ALL`, in that order. */
	providers: ProviderConfig[],
	/**  Seconds between background provider status checks; 0 turns them off. */
	providerHealthCheckSecs: number,
};

export type SourceLimits = {
	source: ProviderKind,
	/**  The provider's display name. */
	name: string,
	outcome: LimitsOutcome,
};

/**
 *  How a SQL Server connection signs in. `EntraAzureCli` sends an access token from the user's
 *  `az login` and saves no password. `Unknown` is a method a newer build saved. Connect and save
 *  refuse it, so the row keeps its method until the user picks one this build knows.
 */
export type SqlServerAuth = "SqlLogin" | "EntraAzureCli" | "Unknown";

export type SqlTypeRef = {
	/**  `"bigint"`, `"integer[]"`, `"order_status"`. */
	display: string,
	category: TypeCategory,
};

export type SshAuth = { kind: "Password" } | 
/**  An OpenSSH private key file, read at each dial. A leading `~` is the home directory. */
{ kind: "Key"; path: string } | 
/**  `None` is the agent at `SSH_AUTH_SOCK`, or the OpenSSH agent pipe on Windows. */
{ kind: "Agent"; socket: string | null };

export type SshError = { kind: "Network"; message: string } | 
/**
 *  No known_hosts file knows this server. `trust` names the key the engine saw, for
 *  `ssh_trust_host_key`; it expires after ten minutes.
 */
{ kind: "HostKeyUnknown"; host: string; port: number; algorithm: string; fingerprint: string; trust: HostKeyId } | 
/**  No known_hosts file holds this key, but one holds another key of its algorithm for the server, at `file:line`. */
{ kind: "HostKeyChanged"; host: string; port: number; algorithm: string; fingerprint: string; knownAt: string } | 
/**  The key is on an `@revoked` line, at `file:line`. */
{ kind: "HostKeyRevoked"; host: string; port: number; algorithm: string; fingerprint: string; revokedAt: string } | 
/**  A known_hosts file exists but cannot be read or parsed, so the key cannot be checked. */
{ kind: "KnownHosts"; message: string } | { kind: "Auth"; message: string } | 
/**  Password auth with no saved password, or an encrypted key with no passphrase. */
{ kind: "MissingSecret" } | { kind: "Key"; message: string } | { kind: "Agent"; message: string } | 
/**  The SSH server refused or failed to open the connection to the database. */
{ kind: "Forward"; message: string };

export type SshTunnel = {
	host: string,
	port: number,
	user: string,
	auth: SshAuth,
	/**  A password for `Password`, or a key passphrase for `Key`, is sealed in the vault. */
	hasSecret: boolean,
};

export type SshTunnelDraft = {
	host: string,
	port: number,
	user: string,
	auth: SshAuth,
	/**
	 *  The password or key passphrase. `Keep` keeps the saved one only while the auth kind is
	 *  unchanged, so a password is never tried as a passphrase.
	 */
	secret: PasswordInput,
};

export type SslMode = "Disable" | "Prefer" | "Require" | "VerifyCa" | "VerifyFull";

export type StatementPlan = {
	planningTimeMs: number | null,
	executionTimeMs: number | null,
	/**  Empty when the server sent no statement text. PostgreSQL plans leave it empty. */
	statementText: string,
	root: PlanNode,
	properties: PlanProperty[],
};

export type StatementRun = {
	outputs: RunOutput[],
	index: number,
	range: DocRange,
	status: StmtStatus,
};

export type StmtStatus = { kind: "Pending" } | { kind: "Preparing" } | { kind: "Running" } | { kind: "Finished" } | { kind: "Failed"; error: QueryError } | { kind: "Cancelled" } | 
/**  An earlier statement failed or was cancelled. */
{ kind: "Skipped" };

export type SynonymInfo = {
	oid: number,
	name: string,
	quoted: string,
	/**  `sys.synonyms.base_object_name`, as stored. The row's detail. */
	target: string,
};

/**  The active tab when the user pressed Send. The engine reads SQL out of `text` itself. */
export type TabContext = {
	tabId: TabId,
	title: string,
	db: DatabaseRef | null,
	text: string,
	/**  UTF-16 offsets, as for `RunRequest::Script`. */
	target: RunTarget,
	/**  The result the tab shows, when the attach button is on. */
	attach: ResultRef | null,
};

/**  Minted by the frontend (`crypto.randomUUID()`). */
export type TabId = string;

export type TabSnapshot = {
	id: TabId,
	title: string,
	/**  `None` only in workspaces written before table tabs saved their text; the frontend seeds the browse query. */
	text: string | null,
	console: ConsoleConfigSnapshot,
	table: TableSnapshot | null,
	/**
	 *  Read only from workspaces saved while a file belonged to one tab, which the frontend moves into a notebook of
	 *  its own. This build writes `None`: a file belongs to a notebook.
	 */
	file: FileSnapshot | null,
};

/**  Staged edits to one table, applied together by `table_apply`. Rows to update or delete are found by primary key. */
export type TableChanges = {
	schema: string,
	table: string,
	/**  Columns left out take their default. */
	inserts: CellWrite[][],
	updates: RowUpdate[],
	/**  Each entry is the primary key of a row to delete. */
	deletes: CellWrite[][],
};

export type TableName = {
	schema: string | null,
	name: string,
};

export type TableOrderEdit = { kind: "Inspect" } | { kind: "Cycle"; column: string; additive: boolean };

export type TableOrderView = {
	sql: string,
	keys: TableSortKey[] | null,
};

export type TableQuery = {
	/**  SQL after `ORDER BY`, e.g. `"created_at" DESC`; empty means primary key order. */
	orderBy: string,
	filters: ColumnFilter[],
	/**  A boolean SQL expression ANDed with `filters`; empty means none. */
	where: string,
};

export type TableScript = {
	text: string,
	/**  Browse documents after trimming outer whitespace. Includes the canonical text. */
	acceptedTexts: string[],
};

/**  The table a tab opened from the sidebar browses, in the tab's console database. */
export type TableSnapshot = {
	schema: string,
	table: string,
	page: number,
	query: TableQuery,
};

export type TableSortKey = {
	column: string,
	desc: boolean,
};

/**  The provider's id for one tool use (`toolu_…` for Claude). Opaque outside the codec. */
export type ToolCallId = string;

export type ToolResult = { kind: "Described"; found: string[]; missing: string[] } | { kind: "Found"; matches: number } | 
/**  The preview the model saw. `more` is true when the query had more rows. */
{ kind: "Rows"; columns: string[]; rows: ((string | null)[])[]; more: boolean; elapsedMs: number };

export type ToolStatus = { kind: "Running" } | { kind: "AwaitingApproval"; approval: ApprovalId; reason: ApprovalReason } | { kind: "Done"; result: ToolResult } | 
/**  `message` is what the model got. */
{ kind: "Failed"; message: string } | 
/**  `stopped` is true when Stop denied it, false when the user pressed Deny. */
{ kind: "Denied"; stopped: boolean } | 
/**  The turn ended before an answer. */
{ kind: "Expired" };

export type ToolUse = { kind: "DescribeTables"; tables: string[] } | { kind: "SearchCatalog"; query: string } | { kind: "RunQuery"; sql: string; purpose: string; relations: string[] } | 
/**  A tool the engine does not serve. Always refused. */
{ kind: "Other"; name: string };

export type TransactionLoss = "None" | "RolledBack" | "Unknown";

export type TriggerEvent = "Insert" | "Update" | "Delete" | "Truncate";

export type TriggerImplementation = { kind: "Function"; name: string } | { kind: "SqlModule"; definition: string | null };

export type TriggerInfo = {
	name: string,
	timing: TriggerTiming,
	/**  In INSERT, UPDATE, DELETE, TRUNCATE order. */
	events: TriggerEvent[],
	perRow: boolean,
	enabled: boolean,
	implementation: TriggerImplementation,
};

export type TriggerTiming = "Before" | "After" | "InsteadOf";

export type TruncateReason = "RowLimit" | "ByteLimit";

export type TurnAccepted = {
	/**  The seq of the stored user entry. */
	turn: number,
};

export type TurnOutcome = { kind: "Completed" } | { kind: "Stopped" } | 
/**  The app quit or crashed mid-turn. Written when the chat next opens. */
{ kind: "Lost" } | { kind: "Failed"; error: AgentError };

export type TurnPhase = "Starting" | "Working" | "AwaitingApproval";

export type TxnError = ({ kind: "Busy" }) & { confirmation?: never } | ({ kind: "NoTransaction" }) & { confirmation?: never } | ({ kind: "RolledBack" }) & { confirmation?: never } | {
	kind: "Query",
} & QueryError | 
/**  Commit would keep writes that ran before the tab's session counted as Production. Nothing was sent. */
{ kind: "ConfirmWrites"; confirmation: WriteConfirmation };

export type TxnMode = "AutoCommit" | "Manual";

/**  `Aborted` permits only rollback. `Open` reports presence without known committability. */
export type TxnState = "Idle" | "Active" | "Aborted" | "Open";

export type TypeCategory = 
/**  int2, int4, int8, oid. */
"Integer" | 
/**  numeric, real, double precision, money. */
"Numeric" | "Text" | "Bool" | "Temporal" | "Json" | "Binary" | "Uuid" | "Network" | "Array" | "Enum" | "Composite" | "Range" | "Other";

export type TypeField = {
	name: string,
	typeName: string,
};

export type TypeInfo = {
	oid: number,
	name: string,
	quoted: string,
	kind: TypeKind,
};

/**  The facts a type row draws. PostgreSQL `typtype` letters stay in the loader. */
export type TypeKind = { kind: "Enum"; labels: string[] } | { kind: "Domain"; base: string } | { kind: "Composite"; fields: TypeField[] } | { kind: "Range"; subtype: string } | 
/**  PostgreSQL `typtype` `b` or `p` in a system schema whose relations loaded. */
{ kind: "Builtin" } | 
/**  SQL Server `CREATE TYPE name FROM ...`. `base` is `display()` of the system type. */
{ kind: "Alias"; base: string; nullable: boolean } | { kind: "Table" };

/**  Keys the file holds that this build does not read, written back on the next save. */
export type UnknownKeys = {
	header: MetaPair[],
	cells: { [key in TabId]: MetaPair[] },
};

export type UpdateError = 
/**  The update is not in the state the action names. The live snapshot already shows where it is. */
{ kind: "Stale" } | 
/**  A track switch while a download or an install runs. */
{ kind: "Busy" };

export type UpdateFailure = { kind: "Offline" } | { kind: "BadSignature" } | 
/**  A mounted disk image or a translocated app cannot replace itself. */
{ kind: "ReadOnlyLocation" } | { kind: "PermissionDenied" } | { kind: "Other"; message: string };

export type UpdateState = {
	rev: number,
	track: UpdateTrack,
	currentVersion: string,
	status: UpdateStatus,
	/**  When the last check came back. A failed check leaves it as it was. */
	checkedAtMs: number | null,
};

export type UpdateStatus = 
/**  Nothing checks. The track can still be chosen. */
{ kind: "Disabled"; reason: UpdatesOff } | { kind: "Idle" } | { kind: "Checking" } | { kind: "UpToDate" } | 
/**
 *  `downgrade` means the release is older than the running build, which happens only for a
 *  nightly build on the Stable track. `changes` lists each release after the running build up
 *  to `version`, newest first.
 */
{ kind: "Available"; version: string; downgrade: boolean; changes: ReleaseChanges[] } | 
/**  `percent` is `None` while the server sends no length. */
{ kind: "Downloading"; version: string; downgrade: boolean; percent: number | null; changes: ReleaseChanges[] } | 
/**  Verified against the built-in key. The engine holds the bytes. */
{ kind: "Downloaded"; version: string; downgrade: boolean; changes: ReleaseChanges[] } | { kind: "Installing"; version: string } | { kind: "Failed"; failure: UpdateFailure };

/**
 *  The release line that update checks follow. `Settings` never holds it, because the webview
 *  writes `Settings` whole and a stale copy there would switch the track back.
 */
export type UpdateTrack = "Stable" | "Nightly";

export type UpdatesOff = "DevBuild" | 
/**  On Linux only the AppImage can replace itself. */
"NotAppImage" | "UnsupportedTarget" | "UnknownVersion";

export type ValueCount = {
	value: string,
	count: number,
};

/**
 *  One edit to a connection's stored view, sent by the pickers. Each is an intent that the engine
 *  resolves against its own current database list and catalogs, so two quick clicks cannot lose
 *  an update the way a selection computed from a stale snapshot would. Every edit is idempotent.
 */
export type ViewEdit = { kind: "Databases"; preset: Preset } | 
/**
 *  One checkbox of the database picker. Showing a database whose stored schema selection
 *  resolves to no schema resets that selection to `DefaultOnly`.
 */
{ kind: "Database"; name: string; shown: boolean } | { kind: "ShowSystemDatabases"; show: boolean } | { kind: "Schemas"; database: string; preset: Preset } | 
/**  One checkbox of the schema picker. */
{ kind: "Schema"; database: string; name: string; shown: boolean } | { kind: "ShowSystemSchemas"; database: string; show: boolean };

/**  Owned by the frontend, stored verbatim by the engine (single writer: the UI). */
export type Workspace = {
	/**  Every cell of every notebook, so a build from before notebooks still opens them all. */
	tabs: TabSnapshot[],
	/**  The shown notebook's active cell, kept so a build from before notebooks still opens it. */
	active: TabId | null,
	layout: Layout,
	notebooks: NotebookSnapshot[],
	/**  `None` shows the start commands. */
	shown: NotebookId | null,
};

/**  The engine ran nothing. Ask the user, then send the same request again with `digest`. */
export type WriteConfirmation = {
	/**  The connection's name. */
	connection: string,
	database: string,
	unit: ExecutionUnitKind,
	sends: WriteList,
	/**
	 *  The writes that ran before the tab's session counted as Production, in a transaction the engine has not seen
	 *  end. Any run on the tab, and Commit, can commit them.
	 */
	holds: WriteList,
	digest: WriteDigest,
	/**  True when the saved connection or the opened session is Production. */
	onProduction: boolean,
};

/**
 *  Opaque. It names the exact statements a guarded action sends, the connection both as saved and as the tab's
 *  session opened it, and the tab's database, schema, mode, and transaction state. The engine makes one when it
 *  refuses a write on Production and accepts it back only while all of that is unchanged.
 */
export type WriteDigest = string;

export type WriteList = {
	count: number,
	/**  The first three statements, or SQL Server batches, trimmed and cut at 2,000 characters. */
	statements: string[],
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

